import pathlib
R=pathlib.Path(__file__).resolve().parent
extra='''CREATE TRIGGER device_entry_document_consistent BEFORE INSERT ON device_view_entries WHEN json_extract(new.document_json,'$.entry_id') IS NOT new.entry_id OR json_extract(new.document_json,'$.entity_kind') IS NOT new.entity_kind OR json_extract(new.document_json,'$.state') IS NOT new.state OR json_type(new.document_json,'$.schema_hash') IS NULL OR json_extract(new.document_json,'$.schema_hash') IS NOT new.schema_hash OR json_type(new.document_json,'$.graph_digest') IS NULL OR json_extract(new.document_json,'$.graph_digest') IS NOT new.graph_digest OR json(json_extract(new.document_json,'$.reason_codes')) IS NOT json(new.reason_codes_json) OR json(json_extract(new.document_json,'$.dependencies')) IS NOT json(new.dependencies_json) OR EXISTS(SELECT 1 FROM json_each(new.reason_codes_json) WHERE type<>'text' OR length(value)=0) BEGIN SELECT RAISE(ABORT,'Device entry JSON disagrees with authoritative columns'); END;
CREATE TRIGGER device_header_document_consistent BEFORE INSERT ON device_views WHEN json_extract(new.document_json,'$.schema_version') IS NOT '2.0.0' OR json_extract(new.document_json,'$.view_id') IS NOT new.view_id OR json_extract(new.document_json,'$.facts_id') IS NOT new.facts_id OR json_extract(new.document_json,'$.registry_id') IS NOT new.registry_id OR json_extract(new.document_json,'$.catalog_generation') IS NOT new.catalog_generation OR json_extract(new.document_json,'$.overlay_generation') IS NOT new.overlay_generation OR json_extract(new.document_json,'$.capability_epoch') IS NOT new.capability_epoch OR json_extract(new.document_json,'$.view_generation') IS NOT new.view_generation OR json_extract(new.document_json,'$.inventory_count') IS NOT new.inventory_count OR json_type(new.document_json,'$.entries') IS NOT NULL BEGIN SELECT RAISE(ABORT,'Device header JSON disagrees with immutable metadata'); END;
'''
for p in (R/'device_view_ddl.sql',R/'catalog/bridge-config.sql'):
    s=p.read_text();assert 'CREATE TRIGGER device_entry_document_consistent' not in s
    s=s.replace('COMMIT;',extra+'COMMIT;') if p.name=='bridge-config.sql' else s+extra
    p.write_text(s)
